/**
 * Frontend data loader for The AI Native.
 *
 * Reads `data/items.json` (generated by scripts/export.py from the SQLite DB).
 * The Python pipeline is the source of truth; this is a static snapshot
 * regenerated on each pipeline run and committed to git so Vercel can build.
 */
import fs from "node:fs";
import path from "node:path";

export type Section = "Organization" | "HR" | "Industry";

// HR sub-modules per PRD §6.1. Display priority order set by the editor.
// 7 modules: 学发→L&D label change + HRBP added as new (May 2026).
export type HRModule =
  | "组织设计"
  | "薪酬"
  | "绩效"
  | "员工体验"
  | "HRBP"
  | "L&D"
  | "招聘";

export const HR_MODULE_ORDER: HRModule[] = [
  "组织设计",
  "薪酬",
  "绩效",
  "员工体验",
  "HRBP",
  "L&D",
  "招聘",
];

// ANO Framework — 8 dimensions of an AI Native Organization (the
// product's proprietary lens, June 2026). Replaces the earlier
// 10-category insight_class taxonomy.
export type AnoDimension =
  | "Leadership"
  | "Organization Design"
  | "Talent"
  | "Performance"
  | "Knowledge"
  | "Agent Workforce"
  | "Decision Making"
  | "Operating System";

/** Chinese gloss displayed alongside each ANO dimension on cards. */
export const ANO_DIMENSION_LABELS: Record<AnoDimension, string> = {
  Leadership: "领导力",
  "Organization Design": "组织设计",
  Talent: "人才",
  Performance: "绩效",
  Knowledge: "知识",
  "Agent Workforce": "Agent 团队",
  "Decision Making": "决策",
  "Operating System": "运行系统",
};

export type Item = {
  id: number;
  url: string;
  title: string;
  source: string;
  source_type: string;
  section: Section | null;
  hr_module: HRModule | null;
  sub_tag: string | null;
  hook: string | null;
  // Legacy fields (v1) — kept for back-compat during migration
  summary: string | null;
  implication: string | null;
  // v2 §3 structured intelligence fields
  what_happened: string | null;
  why_matters: string | null;
  org_implication: string | null;
  talent_implication: string | null;
  hr_operating_implication: string | null;
  prediction: string | null;
  ano_dimension: AnoDimension | null;
  // v5 LaterCast-style long-form Chinese narrative (2500-3500 chars).
  // When present, it's the primary reader surface — cards link to the
  // full article page. `preview_hook` is a one-line teaser for the card.
  long_form_zh: string | null;
  preview_hook: string | null;
  author: string | null;
  published_at: string | null;
  issue_number: number | null;
  perspective_score: number | null;
  practice_score: number | null;
  frontier_score: number | null;
  score_reasoning: string | null;
  total_score: number;
  is_featured: boolean;
};

export type Issue = {
  number: string;
  date_iso: string;
  date_label: string;
};

/** Full issue record with bound items — used by /issues/[number] pages. */
export type IssueRecord = {
  number: number;
  date_iso: string;
  date_label: string;
  frozen_at: string;
  item_count: number;
  item_ids: number[];
};

export type Skill = {
  id: string;
  name: string;
  vendor: string;
  category: string;
  one_line: string;
  summary: string;
  url: string;
  featured: boolean;
};

export type Payload = {
  issue: Issue;
  issues: IssueRecord[];
  current_issue_number: number | null;
  generated_at: string;
  min_score_threshold: number;
  item_count: number;
  featured_count: number;
  items: Item[];
  skills: Skill[];
};

function dataPath(): string {
  return path.resolve(process.cwd(), "data", "items.json");
}

// No cache: file reads are cheap; `next build` reads once per static page.
export function loadPayload(): Payload {
  const raw = fs.readFileSync(dataPath(), "utf-8");
  return JSON.parse(raw) as Payload;
}

export function getAllItems(): Item[] {
  return loadPayload().items;
}

export function getFeatured(section?: Section): Item[] {
  const items = loadPayload().items.filter((i) => i.is_featured);
  return section ? items.filter((i) => i.section === section) : items;
}

/** Items bound to the current (latest) published Issue. */
function currentIssueItems(): Item[] {
  const issue = getCurrentIssue();
  return issue ? getIssueItems(issue.number) : [];
}

/**
 * Homepage section block: prefer the fresh weekly featured set, but fall
 * back to the current Issue's items for this section when no fresh set
 * exists — so the homepage is never empty just because the pipeline
 * hasn't run this week. Issue pages remain the permanent record.
 */
export function getHomeSignals(section: Section): Item[] {
  const featured = getFeatured(section);
  if (featured.length > 0) return featured;
  return currentIssueItems().filter((i) => i.section === section);
}

/**
 * Strict freshness gate for site-wide display per editor directive:
 * articles older than 180 days are never surfaced as "current content"
 * on section archive pages. Permanent Issue pages are excepted —
 * they're date-stamped historical records.
 */
const FRESHNESS_DAYS = 7;  // editor v3.4: was 180, now strict weekly

function isFreshEnough(item: Item): boolean {
  if (!item.published_at) return false; // unknown date treated as old
  const ms = Date.parse(item.published_at);
  if (isNaN(ms)) return false;
  const ageMs = Date.now() - ms;
  return ageMs <= FRESHNESS_DAYS * 24 * 60 * 60 * 1000;
}

export function getBySection(section: Section): Item[] {
  return loadPayload()
    .items
    .filter((i) => i.section === section)
    .filter(isFreshEnough);
}

/** Includes old items — only used by Issue pages where date-stamped context is explicit. */
export function getBySectionAllTime(section: Section): Item[] {
  return loadPayload().items.filter((i) => i.section === section);
}

export function getIssue(): Issue {
  return loadPayload().issue;
}

export function getSkills(): Skill[] {
  return loadPayload().skills;
}

export function getFeaturedSkill(): Skill | undefined {
  return loadPayload().skills.find((s) => s.featured);
}

// ── Issues ─────────────────────────────────────────────────────────

export function getAllIssues(): IssueRecord[] {
  return loadPayload().issues;
}

export function getCurrentIssue(): IssueRecord | null {
  const issues = loadPayload().issues;
  return issues[0] ?? null;
}

export function getIssueByNumber(n: number): IssueRecord | undefined {
  return loadPayload().issues.find((i) => i.number === n);
}

/** Items bound to a specific issue, in display order. */
export function getIssueItems(issueNumber: number): Item[] {
  const issue = getIssueByNumber(issueNumber);
  if (!issue) return [];
  const byId = new Map(loadPayload().items.map((i) => [i.id, i]));
  return issue.item_ids
    .map((id) => byId.get(id))
    .filter((x): x is Item => !!x);
}

/**
 * Top N signals for the homepage hero — selection criteria:
 *   1) passed AI Native relevance gate (~67% of raw input is filtered out)
 *   2) total_score >= 9 across perspective / practice / frontier dimensions
 *   3) summarized into 6-field structured intelligence
 *   4) published in the last 180 days (freshness gate)
 *   5) MAX 1 item per source — source diversity rule
 *   6) At least 1 Organization-section item if any qualified one exists —
 *      structural guarantee for CEO/founder一号位 audience (PRD v3, June 2026)
 */
export function getTopSignals(n: number = 5): Item[] {
  let items = loadPayload().items.filter(
    (i) => i.is_featured && i.what_happened,
  );

  // Fallback: when the weekly pipeline hasn't produced a fresh featured set
  // (e.g. no items in the 7-day window), surface the current published
  // Issue's items instead so the hero is never empty.
  if (items.length === 0) {
    items = currentIssueItems().filter((i) => i.what_happened);
  }

  // Pass 1 — try to seat at least 1 Organization item (highest-scored, fresh,
  // featured). If found, lock it in before diversity/score-ranking the rest.
  const orgPick = items.find((i) => i.section === "Organization");
  const picked: Item[] = [];
  const seenSources = new Set<string>();
  if (orgPick) {
    picked.push(orgPick);
    seenSources.add(orgPick.source);
  }

  // Pass 2 — fill remaining slots by score order, applying diversity rule.
  for (const item of items) {
    if (picked.length >= n) break;
    if (orgPick && item.id === orgPick.id) continue;
    if (seenSources.has(item.source)) continue;
    picked.push(item);
    seenSources.add(item.source);
  }

  return picked;
}

export function getStats(): { items: number; featured: number; skills: number; sources: number } {
  const p = loadPayload();
  const sources = new Set(p.items.map((i) => i.source)).size;
  return {
    items: p.item_count,
    featured: p.featured_count,
    skills: p.skills.length,
    sources,
  };
}

